import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';

describe('ToolRegistry validation (acceptance)', () => {
  const noop: ToolExecutor = async () => 'ok';

  it('ToolRegistry.execute validates input against schema', async () => {
    const registry = new ToolRegistry();
    let called = false;
    const executor: ToolExecutor = async () => {
      called = true;
      return 'ok';
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    // Call with missing required property
    const response = await registry.execute('test_tool', {});

    expect(response.result).toMatch(/location/);
    expect(called).toBe(false);
  });

  it('unlisted extra properties are passed through', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> = {};
    const executor: ToolExecutor = async input => {
      receivedInput = input;
      return 'ok';
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            known: {type: 'string'},
          },
        },
      },
      executor
    );

    const input = {known: 'value', unknown: 'extra'};
    await registry.execute('test_tool', input);

    expect(receivedInput).toEqual(input);
  });

  it('validation error messages do not contain property values', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {
            secret: {type: 'string', enum: ['allowed']},
          },
        },
      },
      noop
    );

    const sensitiveValue = 'MY_SECRET_PASSWORD';
    const response = await registry.execute('test_tool', {secret: sensitiveValue});

    expect(response.result).toContain('secret');
    expect(response.result).not.toContain(sensitiveValue);
  });

  it('register throws for uncompilable schema', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {
      type: 'object',
      properties: {
        foo: {type: 'not-a-type'},
      },
    };

    expect(() => {
      registry.register(
        {
          name: 'bad_tool',
          description: 'test',
          inputSchema: invalidSchema as any,
        },
        noop
      );
    }).toThrow(/bad_tool/);
  });

  it('execute still throws for unknown tool', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('non_existent', {})).rejects.toThrow('Unknown tool: non_existent');
  });

  it('function-valued tool definitions use current schema', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    const definitionSource = () => ({
      name: 'dynamic_tool',
      description: 'test',
      inputSchema: {
        type: 'object',
        properties: {
          val: {type: schemaType},
        },
      },
    });

    registry.register(definitionSource, noop);

    // First call expects string
    const res1 = await registry.execute('dynamic_tool', {val: 123});
    expect(res1.result).toMatch(/string/);

    // Change schema to expect number
    schemaType = 'number';
    const res2 = await registry.execute('dynamic_tool', {val: 123});
    expect(res2.result).toBe('ok');
  });

  it('static tool schema is compiled once', async () => {
    // This is hard to observe directly without spying on Ajv, 
    // but the ticket asks for it. We'll use a proxy to count accesses 
    // to the inputSchema object as a proxy for "something looked at it".
    // Actually, Ajv compilation might happen once and then it's cached.

    const inputSchema = {
      type: 'object',
      properties: { val: { type: 'string' } }
    };

    let accessCount = 0;
    const proxySchema = new Proxy(inputSchema, {
      get(target, prop, receiver) {
        if (prop === 'type' || prop === 'properties') {
          accessCount++;
        }
        return Reflect.get(target, prop, receiver);
      }
    });

    const registry = new ToolRegistry();
    registry.register({
      name: 'cached_tool',
      description: 'test',
      inputSchema: proxySchema as any
    }, noop);

    // Accesses during register()
    const initialAccesses = accessCount;

    for (let i = 0; i < 10; i++) {
      await registry.execute('cached_tool', { val: 'ok' });
    }

    // Should not have accessed the schema object more times during execution
    expect(accessCount).toBe(initialAccesses);
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('ChatOrchestrator tool loop validation (acceptance)', () => {
  const promptBuilder = new PromptBuilder({identity: 'Test'});
  const SENT_AT = '2026-01-01T00:00:00.000Z';

  function createSession(content: string): ChatSession {
    return {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content, timestamp: SENT_AT}],
    };
  }

  it('tool loop handles rejected call and corrected retry', async () => {
    const registry = new ToolRegistry();
    let executorCalledWith: any = null;

    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      async (input) => {
        executorCalledWith = input;
        return 'The weather is sunny';
      }
    );

    // Mock provider that first sends a bad call, then a good one
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        if (round === 0) {
          round++;
          // Bad call: missing location
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-1', name: 'weather', input: {}}
          };
          yield {type: 'stop', stopReason: 'tool_use'};
        } else if (round === 1) {
          round++;
          // Verify we saw the error in the history
          const lastMessage = params.messages[params.messages.length - 1];
          if (lastMessage.role === 'user' && Array.isArray(lastMessage.content)) {
            const toolResult = lastMessage.content[0];
            if (toolResult.type === 'tool_result' && toolResult.content.includes('location')) {
              // Corrected call
              yield {
                type: 'tool_use',
                toolCall: {id: 'call-2', name: 'weather', input: {location: 'Berlin'}}
              };
              yield {type: 'stop', stopReason: 'tool_use'};
            }
          }
        } else {
          yield {type: 'text', text: 'All done!'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('weather?'));

    expect(executorCalledWith).toEqual({location: 'Berlin'});
    expect(result).toContain('All done!');
  });
});

